// WebWell Plus: the sound mixer panel inside the music card (Sounds tab).
// Layers are generated by the offscreen player (offscreen.js, "sound mixer"); this file only
// shows the sliders, keeps the user's mixes and sends levels. It relies on music.js for
// playerSend / uiState / musicState, and on newtab.js for window.wwPlus.
// Storage: plusMixes = [{ id, name, levels, master }], plusMixLast = { levels, master, name }.
'use strict';

(function () {
  const SOUNDS = [
    { k: 'rain', name: 'Rain' }, { k: 'waves', name: 'Waves' },
    { k: 'brown', name: 'Brown noise' }, { k: 'soft', name: 'Soft noise' },
    { k: 'cafe', name: 'Cafe' }, { k: 'fire', name: 'Fireplace' },
    { k: 'wind', name: 'Wind' }, { k: 'crickets', name: 'Crickets' }
  ];
  const FIRST_MIX = { rain: 0.5, soft: 0.25 };
  const MAX_MIXES = 20;
  const $x = id => document.getElementById(id);
  const esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const isPlus = () => !!(window.wwPlus && window.wwPlus.on);
  const sendP = m => (typeof playerSend === 'function' ? playerSend(m) : Promise.reject()).catch(() => null);

  let levels = {}, master = 0.8, name = '', mixes = [], open = false, loaded = false, note = '';
  const mixPlaying = () => typeof uiState !== 'undefined' && uiState.kind === 'mix' && !!uiState.playing && uiState.tab === 'ambient';
  const anyUp = () => SOUNDS.some(s => levels[s.k] > 0);
  const pctText = v => v > 0 ? Math.round(v * 100) + ' percent' : 'Off';

  function saveLast() {
    clearTimeout(saveLast._t);
    saveLast._t = setTimeout(() => { try { chrome.storage.local.set({ plusMixLast: { levels, master, name } }); } catch (e) {} }, 400);
  }
  // So the pill's play button and "pick up where you left off" bring the mix back.
  function rememberAsLast() {
    if (typeof musicState === 'undefined') return;
    musicState.last = { id: 'ambient:mix', kind: 'mix', title: name || 'Your mix' };
    if (typeof saveMusicState === 'function') saveMusicState();
  }

  function play() {
    if (!isPlus()) return false;
    if (!anyUp()) levels = Object.assign({}, FIRST_MIX);
    rememberAsLast();
    sendP({ cmd: 'mixer-play', levels, master, name });
    renderPanel();
    return true;
  }
  function stop() { sendP({ cmd: 'mixer-stop' }); }

  // Slider moves are sent at most every 80 ms; the player smooths the change itself.
  let pend = null;
  function pushLevels() {
    if (pend) return;
    pend = setTimeout(() => {
      pend = null;
      if (mixPlaying()) sendP({ cmd: 'mixer-set', levels, master, name });
      else if (anyUp()) { rememberAsLast(); sendP({ cmd: 'mixer-play', levels, master, name }); }
    }, 80);
  }

  function sliderHtml(id, label, v, dis) {
    return '<div class="mix-row"><label for="' + id + '">' + esc(label) + '</label>' +
      '<input type="range" id="' + id + '" min="0" max="100" step="1" value="' + Math.round(v * 100) + '"' + (dis ? ' disabled tabindex="-1"' : '') +
      ' aria-valuetext="' + pctText(v) + '" style="--v:' + Math.round(v * 100) + '%"></div>';
  }

  function renderPanel() {
    const box = $x('mixPanel');
    if (!box || !open) return;
    const back = '<button type="button" class="mix-back" id="mixBack" aria-label="Back to sounds">‹ Sounds</button>';
    if (!isPlus()) {
      const sample = { rain: 0.6, cafe: 0.35, fire: 0.5, wind: 0.2 };
      box.innerHTML = '<div class="mix-head">' + back + '</div>' + (typeof plusLockHtml === 'function' ? plusLockHtml('mixer') : '') +
        '<div class="mix-grid mix-preview" aria-hidden="true">' + SOUNDS.map(s => sliderHtml('mixp-' + s.k, s.name, sample[s.k] || 0, true)).join('') + '</div>';
      if (typeof plusWireLocks === 'function') plusWireLocks(box);
      wireBack();
      return;
    }
    const playing = mixPlaying();
    box.innerHTML =
      '<div class="mix-head">' + back +
        '<button type="button" class="mix-play' + (playing ? ' on' : '') + '" id="mixPlay" aria-pressed="' + playing + '">' + (playing ? 'Pause mix' : 'Play mix') + '</button></div>' +
      '<div class="mix-master">' + sliderHtml('mixMaster', 'Volume', master) + '</div>' +
      '<div class="mix-grid" role="group" aria-label="Sound levels">' + SOUNDS.map(s => sliderHtml('mix-' + s.k, s.name, levels[s.k] || 0)).join('') + '</div>' +
      '<p class="mhead">Your mixes</p>' +
      '<div class="mix-chips" id="mixChips">' + (mixes.length ? mixes.map(m =>
        '<span class="mix-chip' + (m.name === name ? ' on' : '') + '"><button type="button" data-load="' + esc(m.id) + '">' + esc(m.name) + '</button>' +
        '<button type="button" class="mix-del" data-del="' + esc(m.id) + '" aria-label="Delete the mix ' + esc(m.name) + '">✕</button></span>').join('')
        : '<span class="mix-empty">Saved mixes appear here.</span>') + '</div>' +
      '<div class="mrow-in mix-save"><input id="mixName" type="text" maxlength="40" placeholder="Name this mix" autocomplete="off" aria-label="Name for this mix" value="' + esc(name) + '">' +
        '<button type="button" id="mixSave">Save</button></div>' +
      '<p class="mix-note" id="mixNote" aria-live="polite">' + esc(note) + '</p>';
    wireBack();
    $x('mixPlay').addEventListener('click', () => { if (mixPlaying()) stop(); else play(); });
    box.querySelectorAll('input[type="range"]').forEach(inp => inp.addEventListener('input', () => {
      const v = (+inp.value) / 100;
      inp.setAttribute('aria-valuetext', pctText(v)); inp.style.setProperty('--v', inp.value + '%');
      if (inp.id === 'mixMaster') master = v; else levels[inp.id.slice(4)] = v;
      pushLevels(); saveLast();
    }));
    $x('mixSave').addEventListener('click', saveMix);
    $x('mixName').addEventListener('keydown', e => { if (e.key === 'Enter') saveMix(); });
    $x('mixChips').addEventListener('click', e => {
      const b = e.target.closest('button'); if (!b) return;
      if (b.dataset.load) loadMix(b.dataset.load);
      else if (b.dataset.del) deleteMix(b.dataset.del);
    });
  }
  function wireBack() { $x('mixBack').addEventListener('click', () => { setOpen(false); $x('mixEntry').focus(); }); }

  function persistMixes() { try { chrome.storage.local.set({ plusMixes: mixes }); } catch (e) {} }
  function saveMix() {
    const inp = $x('mixName');
    if (!anyUp()) { note = 'Turn at least one sound up first.'; renderPanel(); return; }
    const nm = (inp.value.trim() || 'Mix ' + (mixes.length + 1)).slice(0, 40);
    const i = mixes.findIndex(m => m.name.toLowerCase() === nm.toLowerCase());
    const m = { id: i >= 0 ? mixes[i].id : 'm' + Date.now().toString(36), name: nm, levels: Object.assign({}, levels), master };
    if (i >= 0) mixes[i] = m; else { mixes.unshift(m); if (mixes.length > MAX_MIXES) mixes.length = MAX_MIXES; }
    name = nm; note = (i >= 0 ? 'Updated ' : 'Saved ') + nm + '.';
    persistMixes(); saveLast();
    if (mixPlaying()) sendP({ cmd: 'mixer-set', levels, master, name });
    renderPanel();
  }
  function loadMix(id) {
    const m = mixes.find(x => x.id === id); if (!m) return;
    levels = Object.assign({}, m.levels); master = typeof m.master === 'number' ? m.master : master; name = m.name; note = '';
    saveLast(); play();
  }
  function deleteMix(id) {
    const m = mixes.find(x => x.id === id); if (!m) return;
    mixes = mixes.filter(x => x.id !== id);
    if (name === m.name) name = '';
    note = 'Deleted ' + m.name + '.';
    persistMixes(); saveLast(); renderPanel();
    const first = document.querySelector('#mixChips button'); (first || $x('mixName')).focus();
  }

  function setOpen(v) {
    open = v;
    note = '';
    $x('mixPanel').classList.toggle('hidden', !v);
    $x('ambientList').classList.toggle('hidden', v);
    $x('mixEntry').classList.toggle('hidden', v);
    $x('mixEntry').setAttribute('aria-expanded', v ? 'true' : 'false');
    if (v) { renderPanel(); const f = $x('mixPlay') || document.querySelector('#mixPanel .plus-btn'); if (f) f.focus(); }
  }

  // Called by music.js after every player update: only the small bits that change.
  function sync() {
    const sub = $x('mixEntrySub'), badge = $x('mixEntryBadge');
    if (!sub) return;
    // Plus has ended (or the key ran out) and the player still holds a mix: have it forget the mix,
    // so play buttons elsewhere (popup, focus screen) cannot bring a locked feature back.
    if (window.wwPlus && window.wwPlus.checked && !isPlus() && typeof uiState !== 'undefined' && uiState.kind === 'mix' && !sync._forgot) {
      sync._forgot = true; sendP({ cmd: 'mixer-forget' });
    }
    badge.innerHTML = isPlus() ? '' : '<span class="plus-badge">Plus</span>';
    sub.textContent = mixPlaying() ? 'Playing ' + (name || 'your mix') : 'Layer sounds at your own levels';
    $x('mixEntry').classList.toggle('active', mixPlaying());
    const pb = $x('mixPlay');
    if (pb && open) { const on = mixPlaying(); pb.textContent = on ? 'Pause mix' : 'Play mix'; pb.classList.toggle('on', on); pb.setAttribute('aria-pressed', on); }
  }

  async function init() {
    if (!$x('mixEntry')) return;
    try {
      const r = await chrome.storage.local.get(['plusMixes', 'plusMixLast']);
      mixes = Array.isArray(r.plusMixes) ? r.plusMixes.filter(m => m && m.id && m.name && m.levels) : [];
      const last = r.plusMixLast || {};
      levels = last.levels && typeof last.levels === 'object' ? last.levels : {};
      if (typeof last.master === 'number') master = last.master;
      name = last.name || '';
    } catch (e) {}
    loaded = true;
    $x('mixEntry').addEventListener('click', () => setOpen(true));
    $x('mixPanel').addEventListener('keydown', e => { if (e.key === 'Escape' && open) { e.stopPropagation(); setOpen(false); $x('mixEntry').focus(); } });
    // Switching tabs or closing the card resets to the list next time.
    document.querySelectorAll('.music-tab').forEach(t => t.addEventListener('click', () => { if (open) setOpen(false); }));
    if (window.wwPlus) window.wwPlus.onChange(on => {
      // Plus ended while a mix plays: stop it quietly instead of leaving a feature running that is now locked.
      if (on) sync._forgot = false;
      sync(); if (open) renderPanel();
    });
    sync();
  }

  window.WWMixer = { play, stop, sync, isPlaying: mixPlaying, get loaded() { return loaded; }, SOUNDS };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();
